     1→import Database from 'better-sqlite3';
     2→import path from 'path';
     3→import fs from 'fs';
     4→
     5→const DB_PATH = path.join(process.cwd(), 'database', 'sangsi.db');
     6→const SCHEMA_PATH = path.join(process.cwd(), 'database', 'schema.sql');
     7→
     8→// Ensure the database directory exists
     9→const dbDir = path.dirname(DB_PATH);
    10→if (!fs.existsSync(dbDir)) {
    11→  fs.mkdirSync(dbDir, { recursive: true });
    12→}
    13→
    14→const db = new Database(DB_PATH);
    15→
    16→// Enable WAL mode for better performance
    17→db.pragma('journal_mode = WAL');
    18→db.pragma('foreign_keys = ON');
    19→
    20→// Initialize schema on module load
    21→const schema = fs.readFileSync(SCHEMA_PATH, 'utf-8');
    22→db.exec(schema);
    23→
    24→export default db;
    25→

