    67→
    68→export default function CandidateForm({
    69→  candidates,
    70→  onCandidatesChange,
    71→}: CandidateFormProps) {
    72→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
    73→
    74→  const toggleExpanded = (id: string) => {
    75→    setExpandedIds((prev) => {
    76→      const next = new Set(prev);
    77→      next.has(id) ? next.delete(id) : next.add(id);
    78→      return next;
    79→    });
    80→  };
    81→
    82→  const addCandidate = () => {
    83→    const newCandidate: CandidateRow = {
    84→      _id: generateId(),
    85→      name: '',
    86→      birth_year: '',
    87→      current_affiliation: '',
    88→      current_position: '',
    89→      major_field: '',
    90→      total_papers: '',
    91→      jcr_ratio: '',
    92→      fwci: '',
    93→      remarks: '',
    94→      degrees: [],
    95→      careers: [],
    96→    };
    97→    onCandidatesChange([...candidates, newCandidate]);
    98→  };
    99→
   100→  const deleteCandidate = (id: string) => {
   101→    onCandidatesChange(candidates.filter((c) => c._id !== id));
   102→    setExpandedIds((prev) => {
   103→      const next = new Set(prev);
   104→      next.delete(id);
   105→      return next;
   106→    });
   107→  };
   108→
   109→  const updateCandidate = (id: string, key: keyof CandidateRow, value: string) => {
   110→    onCandidatesChange(
   111→      candidates.map((c) => (c._id === id ? { ...c, [key]: value } : c))
   112→    );
   113→  };
   114→
   115→  const updateCandidateNested = (id: string, updater: (c: CandidateRow) => CandidateRow) => {
   116→    onCandidatesChange(candidates.map((c) => (c._id === id ? updater(c) : c)));
   117→  };
   118→
   119→  // Degree handlers
   120→  const addDegree = (candidateId: string) => {
   121→    updateCandidateNested(candidateId, (c) => ({
   122→      ...c,
   123→      degrees: [
   124→        ...c.degrees,
   125→        { _id: generateId(), school: '', major: '', degree_year: '', degree_type: '' },
   126→      ],
   127→    }));
   128→  };
   129→
   130→  const deleteDegree = (candidateId: string, degreeId: string) => {
   131→    updateCandidateNested(candidateId, (c) => ({
   132→      ...c,
