   169→  return (
   170→    <div className="space-y-6">
   171→      {/* 후보자 심사요청서 테이블 */}
   172→      <div className="section-card">
   173→        <h2 className="section-title">후보자 심사요청서</h2>
   174→        <DynamicTable
