   177→          onAddRow={addCandidate}
   178→          onDeleteRow={deleteCandidate}
   179→          onUpdateRow={(id, key, value) => updateCandidate(id, key as keyof CandidateRow, value)}
   180→          addLabel="+ 후보자 추가"
   181→          emptyMessage="후보자가 없습니다. 후보자를 추가해주세요."
   182→        />
   183→      </div>
   184→
   185→      {/* 학위 및 경력 사항 섹션 */}
   186→      {candidates.length > 0 && (
   187→        <div className="section-card">
   188→          <h2 className="section-title">학위 및 경력 사항</h2>
   189→          <div className="space-y-3">
   190→            {candidates.map((candidate, index) => {
   191→              const isExpanded = expandedIds.has(candidate._id);
   192→              return (
   193→                <div key={candidate._id} className="border border-gray-200 rounded-lg overflow-hidden">
   194→                  <button
   195→                    type="button"
