   216→                          rows={candidate.degrees}
   217→                          onAddRow={() => addDegree(candidate._id)}
   218→                          onDeleteRow={(id) => deleteDegree(candidate._id, id)}
   219→                          onUpdateRow={(id, key, value) =>
