   231→                          onAddRow={() => addCareer(candidate._id)}
   232→                          onDeleteRow={(id) => deleteCareer(candidate._id, id)}
   233→                          onUpdateRow={(id, key, value) =>
   234→                            updateCareer(candidate._id, id, key as keyof CareerRow, value)
   235→                          }
   236→                          addLabel="+ 경력 추가"
   237→                          emptyMessage="경력 정보가 없습니다."
   238→                        />
   239→                      </div>
   240→                    </div>
   241→                  )}
   242→                </div>
   243→              );
   244→            })}
   245→          </div>
   246→        </div>
   247→      )}
   248→    </div>
   249→  );
   250→}
